#!/bin/sh
# Generated by FWShift: rows for the packet filter (and NAT) of a Phoenix Contact mGuard, added with gaiconfig.
# Read the report first: what is not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE            prints the gaiconfig calls; runs anywhere
#   sh THIS_FILE                      on the mGuard (SSH, as root or admin): adds the groups and rows
#   FWSHIFT_APPEND=yes sh THIS_FILE   also when the tables have rows: the new ones go after them
#
# Nothing is changed or deleted, and no interface, route or access to the mGuard is touched. Every call but the last
# writes with --silent; the last one reconfigures, and the rows take effect then. A call gaiconfig refuses stops the
# script: what was written before is stored but not active (the groups start with 'fws_', the rows' comments
# with the names of the rules); remove it in the web interface, or run the script again after fixing the cause.
set -u
DRY_RUN="${DRY_RUN:-}"
FWSHIFT_APPEND="${FWSHIFT_APPEND:-}"
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
gc() {
  if [ -n "$DRY_RUN" ]; then printf 'gaiconfig' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gaiconfig "$@" >/dev/null || fail "gaiconfig $*"
}
rows() {
  if [ -n "$DRY_RUN" ]; then echo 0; return 0; fi
  gaiconfig --get-rowcount "$1" || fail "gaiconfig --get-rowcount $1"
}
named() {
  [ -z "$DRY_RUN" ] && gaiconfig --get "$1" 2>/dev/null | grep -F -q "NAME = \"$2\""
}
if [ -z "$DRY_RUN" ] && ! command -v gaiconfig >/dev/null 2>&1; then fail "gaiconfig not found: run this on the mGuard"; fi
for t in FW_OUTGOING FW_INCOMING_WAN_DMZ FW_OUTGOING_DMZWAN FW_OUTGOING_LANDMZ FW_PORTFORWARDING; do
  n=$(rows "$t")
  if [ "$n" != 0 ] && [ "$FWSHIFT_APPEND" != yes ]; then
    fail "$t has $n rows, which the mGuard would check before the new ones; nothing was written (FWSHIFT_APPEND=yes adds after them)"
  fi
done
named FW_GROUP_PORT fws_default-internet && fail 'a port group named fws_default-internet exists; nothing was written'
named FW_GROUP_PORT fws_web && fail 'a port group named fws_web exists; nothing was written'
named FW_GROUP_IP fws_update-host && fail 'an IP group named fws_update-host exists; nothing was written'
named FW_GROUP_IP fws_rule-18_dst && fail 'an IP group named fws_rule-18_dst exists; nothing was written'
named FW_GROUP_IP fws_servers && fail 'an IP group named fws_servers exists; nothing was written'
named FW_GROUP_IP fws_printers && fail 'an IP group named fws_printers exists; nothing was written'

# FW_GROUP_IP
N=$(rows FW_GROUP_IP)
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_update-host --set .COMMENT 'FWShift: update-host'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP updates.example.com
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_rule-18_dst --set .COMMENT 'FWShift: webserver, external-interface'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 203.0.113.2
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_servers --set .COMMENT 'FWShift: servers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.10
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 172.16.20.25
N=$((N+1))
gc --silent --goto FW_GROUP_IP --add-row --set .NAME fws_printers --set .COMMENT 'FWShift: printers'
gc --silent --goto "FW_GROUP_IP.$N.ENTRY" --add-row --set .IP 192.168.10.200-192.168.10.220
N=$((N+1))

# FW_GROUP_PORT
N=$(rows FW_GROUP_PORT)
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_default-internet --set .COMMENT 'FWShift: default-internet'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 21
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))
gc --silent --goto FW_GROUP_PORT --add-row --set .NAME fws_web --set .COMMENT 'FWShift: web'
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 80
gc --silent --goto "FW_GROUP_PORT.$N.ENTRY" --add-row --set .PORT 443
N=$((N+1))

# FW_OUTGOING
N=$(rows FW_OUTGOING)
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 0 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'rule-1: LAN to the internet'
gc --silent --set-refname "FW_OUTGOING.$N.IN_PORT" fws_default-internet
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO udp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT 53 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'rule-1: LAN to the internet'
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 443 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT rule-11
gc --silent --set-refname "FW_OUTGOING.$N.IN_IP" fws_update-host
N=$((N+1))
gc --silent --goto FW_OUTGOING --add-row --set .PROTO all --set .FROM_IP 0.0.0.0/32 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'rule-3: printers stay inside'
gc --silent --set-refname "FW_OUTGOING.$N.FROM_IP" fws_printers
N=$((N+1))

# FW_INCOMING_WAN_DMZ
N=$(rows FW_INCOMING_WAN_DMZ)
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 443 --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'rule-18: a rule above the forward sees the server'
gc --silent --set-refname "FW_INCOMING_WAN_DMZ.$N.IN_IP" fws_rule-18_dst
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.2 --set .IN_PORT 8443 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'rule-2: publish the web server'
N=$((N+1))
gc --silent --goto FW_INCOMING_WAN_DMZ --add-row --set .PROTO tcp --set .FROM_IP 0.0.0.0/0 --set .FROM_PORT any --set .IN_IP 203.0.113.5 --set .IN_PORT 25 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT 'rule-6: publish the mail server'
N=$((N+1))

# FW_OUTGOING_DMZWAN
N=$(rows FW_OUTGOING_DMZWAN)
gc --silent --goto FW_OUTGOING_DMZWAN --add-row --set .PROTO all --set .FROM_IP 172.16.20.0/24 --set .FROM_PORT any --set .IN_IP 0.0.0.0/0 --set .IN_PORT any --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT rule-8
N=$((N+1))

# FW_OUTGOING_LANDMZ
N=$(rows FW_OUTGOING_LANDMZ)
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.50 --set .FROM_PORT any --set .IN_IP 0.0.0.0/32 --set .IN_PORT 22 --set .TARGET_REF ACCEPT --set .LOG yes --set .COMMENT 'rule-7: administration'
gc --silent --set-refname "FW_OUTGOING_LANDMZ.$N.IN_IP" fws_servers
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 172.16.20.0/24 --set .IN_PORT 8000:8010 --set .TARGET_REF ACCEPT --set .LOG no --set .COMMENT rule-12
N=$((N+1))
gc --silent --goto FW_OUTGOING_LANDMZ --add-row --set .PROTO tcp --set .FROM_IP 192.168.10.0/24 --set .FROM_PORT any --set .IN_IP 172.16.20.25 --set .IN_PORT 25 --set .TARGET_REF DROP --set .LOG no --set .COMMENT 'rule-17: only the mail server sends'
N=$((N+1))

# FW_PORTFORWARDING
N=$(rows FW_PORTFORWARDING)
gc --silent --goto FW_PORTFORWARDING --add-row --set .PROTO tcp --set .SRC_IP 0.0.0.0/0 --set .SRC_PORT any --set .IN_IP 203.0.113.2 --set .IN_PORT 8443 --set .OUT_IP 172.16.20.10 --set .OUT_PORT 443 --set .LOG no --set .COMMENT 'rule-2-nat: DESTNAT of rule-2'
N=$((N+1))
gc --goto FW_PORTFORWARDING --add-row --set .PROTO tcp --set .SRC_IP 0.0.0.0/0 --set .SRC_PORT any --set .IN_IP 203.0.113.5 --set .IN_PORT 25 --set .OUT_IP 172.16.20.25 --set .OUT_PORT 25 --set .LOG no --set .COMMENT 'rule-6-nat: DESTNAT of rule-6'
N=$((N+1))

if [ -z "$DRY_RUN" ]; then
  for v in FW_INCOMING_GLOBAL FW_OUTGOING_GLOBAL; do
    g=$(gaiconfig --get "$v" 2>/dev/null || true)
    [ "$g" = rules ] || printf 'NOTE: %s is %s: the rows take effect only with "Use the firewall ruleset below" (rules)\n' "$v" "$g" >&2
  done
fi
echo 'Done. Check the tables in the web interface (Network Security >> Packet Filter, Network >> NAT).' >&2
